function BodyMap({ selected, onSelect }) {
  return (
    <div className="flex flex-col items-center gap-4 rounded-2xl border border-border bg-panel px-[18px] py-[22px]">
      <div className="font-display self-start text-[10px] tracking-[.16em] text-text-secondary">
        BODY MAP · 탭하여 선택
      </div>
      <svg viewBox="0 0 200 490" className="h-auto w-full max-w-[220px]">
        <path
          d={SILHOUETTE_PATH}
          fill="#1e1e1e"
          stroke="#484848"
          strokeWidth="1.4"
          strokeLinejoin="round"
        />
        {ZONES.map((zone) => {
          const isSelected = selected === zone.value
          return zone.cx.map((cx) => (
            <ellipse
              key={`${zone.value}-${cx}`}
              cx={cx}
              cy={zone.cy}
              rx={zone.rx}
              ry={zone.ry}
              fill={isSelected ? 'rgba(255,106,26,.85)' : 'rgba(255,106,26,0)'}
              stroke={isSelected ? '#ff6a1a' : 'rgba(245,245,245,.22)'}
              strokeWidth={isSelected ? 2 : 1.3}
              className="cursor-pointer"
              onClick={() => onSelect(zone.value)}
            />
          ))
        })}
      </svg>
    </div>
  )
}

export default BodyMap
